#pragma warning disable CA1716
using WhatsBiz.Domain.Purchases;
namespace WhatsBiz.Application.Common.Interfaces;
public sealed record PurchasePostRequest(Guid SupplierId, string? SupplierInvoiceNo, DateTimeOffset InvoiceDate, DateTimeOffset? DueDate, Guid WarehouseId, string ItemsJson, string ExpensesJson, string PaymentsJson, decimal BillDiscount, decimal RoundOff, string? Remarks, string Status, string? User); public sealed record PurchasePostResult(Guid PurchaseInvoiceId, string InvoiceNumber, decimal GrandTotal, decimal PaidAmount, decimal BalanceAmount, string Status); public sealed record PurchasePaymentRequest(Guid PurchaseInvoiceId, string MethodCode, decimal Amount, string? ReferenceNumber, string? User); public sealed record PurchaseReturnRequest(Guid PurchaseInvoiceId, string ItemsJson, string Reason, string? User);
public interface IPurchaseEngine { Task<PurchasePostResult> Post(PurchasePostRequest request, CancellationToken token); Task Pay(PurchasePaymentRequest request, CancellationToken token); Task Return(PurchaseReturnRequest request, CancellationToken token); }
public interface IPurchaseRepository { Task<(IReadOnlyCollection<PurchaseInvoice>, int)> List(string? search, string? status, Guid? supplierId, DateTimeOffset? from, DateTimeOffset? to, int page, int size, CancellationToken token); Task<PurchaseInvoice?> Get(Guid id, bool tracking, CancellationToken token); Task<bool> PurchaseExists(Guid purchaseId, CancellationToken token); Task<PurchaseAttachment?> GetAttachment(Guid purchaseId, Guid attachmentId, bool tracking, CancellationToken token); void AddAttachment(PurchaseAttachment attachment); Task<PurchaseDashboardData> Dashboard(CancellationToken token); Task Save(CancellationToken token); Task SaveAttachments(CancellationToken token); }
public sealed record PurchaseDashboardData(decimal TodayPurchases, int TodayCount, decimal Outstanding, decimal MonthPurchases);
public interface IPurchaseSpreadsheetService { byte[] Export(IReadOnlyCollection<PurchaseInvoice> purchases); byte[] Template(); }
